def calculate_average(numbers):
    total = 0
    for num in numbers:
        total += num
    return total / len(numbers)

print(calculate_average([10, 20, 30]))  # Expected: 20.0
print(calculate_average([]))            # Expected: 0.0
print(calculate_average([-5, 5]))       # Expected: 0.0

def binary_search(arr, target):
    left = 0
    right = len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid
        else:
            right = mid
    return -1

print(binary_search([1, 3, 5, 7, 9], 7))  # Expected: 3
print(binary_search([1, 3, 5, 7, 9], 1))  # Expected: 0
print(binary_search([1, 3, 5, 7, 9], 9))  # Expected: 4

def f(x,y,z):
    a=0
    for i in range(len(x)):
        if x[i]>z:
            a=a+x[i]
    b=0
    for j in range(len(y)):
        if y[j]>z:
            b=b+1
    return a,b

