def process_user(user):
    if user is not None:
        if user.get('active'):
            if user.get('age') >= 18:
                if user.get('balance') > 0:
                    return 'eligible'
                else:
                    return 'no_balance'
            else:
                return 'underage'
        else:
            return 'inactive'
    else:
        return 'no_user'

print(process_user({'active': True, 'age': 25, 'balance': 100}))  # Expected: eligible
print(process_user({'active': True, 'age': 16, 'balance': 100}))  # Expected: underage
print(process_user(None))                                          # Expected: no_user
